import{_ as l,a0 as p,w as r,s as o,I as t,x as a,a1 as i,A as n,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"Stratis 加密入门 | LCTT x X-CMD","titleTemplate":false,"description":"Stratis 加密入门 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Stratis 加密入门 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Stratis 加密入门 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20201109 Getting started with Stratis encryption","title":"Stratis 加密入门","tag":"202104","desc":""},"relativePath":"202104/20201109 Getting started with Stratis encryption.md","filePath":"[post].md"}'),h={name:"202104/20201109 Getting started with Stratis encryption.md"};function c(k,s,g,b,u,y){const e=p("Link");return r(),o("div",null,[s[22]||(s[22]=t("h1",{id:"stratis-加密入门",tabindex:"-1"},[a("Stratis 加密入门 "),t("a",{class:"header-anchor",href:"#stratis-加密入门","aria-label":"Permalink to “Stratis 加密入门”"},"​")],-1)),s[23]||(s[23]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202104/19/094919orzaxwl5axiqqfiu.jpg",alt:""})],-1)),t("p",null,[s[2]||(s[2]=a("Stratis 在其 ",-1)),i(e,{href:"https://stratis-storage.github.io/"},{default:n(()=>[...s[0]||(s[0]=[a("官方网站",-1)])]),_:1}),s[3]||(s[3]=a(" 上被描述为“",-1)),s[4]||(s[4]=t("em",null,"易于使用的 Linux 本地存储管理",-1)),s[5]||(s[5]=a("”。请看这个 ",-1)),i(e,{href:"https://www.youtube.com/watch?v=CJu3kmY-f5o"},{default:n(()=>[...s[1]||(s[1]=[a("短视频",-1)])]),_:1}),s[6]||(s[6]=a("，快速演示基础知识。该视频是在 Red Hat Enterprise Linux 8 系统上录制的。视频中显示的概念也适用于 Fedora 中的 Stratis。",-1))]),s[24]||(s[24]=d(`<p>Stratis 2.1 版本引入了对加密的支持。继续阅读以了解如何在 Stratis 中开始加密。</p><h3 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to “先决条件”">​</a></h3><p>加密需要 Stratis 2.1 或更高版本。这篇文章中的例子使用的是 Fedora 33 的预发布版本。Stratis 2.1 将用在 Fedora 33 的最终版本中。</p><p>你还需要至少一个可用的块设备来创建一个加密池。下面的例子是在 KVM 虚拟机上完成的，虚拟磁盘驱动器为 5GB（<code>/dev/vdb</code>）。</p><h3 id="在内核密钥环中创建一个密钥" tabindex="-1">在内核密钥环中创建一个密钥 <a class="header-anchor" href="#在内核密钥环中创建一个密钥" aria-label="Permalink to “在内核密钥环中创建一个密钥”">​</a></h3><p>Linux 内核<ruby>密钥环<rt>keyring</rt></ruby>用于存储加密密钥。关于内核密钥环的更多信息，请参考 <code>keyrings</code> 手册页（<code>man keyrings</code>）。</p><p>使用 <code>stratis key set</code> 命令在内核钥匙圈中设置密钥。你必须指定从哪里读取密钥。要从标准输入中读取密钥，使用 <code>-capture-key</code> 选项。要从文件中读取密钥，使用 <code>-keyfile-path &lt;file&gt;</code> 选项。最后一个参数是一个密钥描述。它将稍后你创建加密的 Stratis 池时使用。</p><p>例如，要创建一个描述为 <code>pool1key</code> 的密钥，并从标准输入中读取密钥，可以输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis key set --capture-key pool1key</span></span>
<span class="line"><span>Enter desired key data followed by the return key:</span></span></code></pre></div><p>该命令提示我们输入密钥数据/密码，然后密钥就创建在内核密钥环中了。</p><p>要验证密钥是否已被创建，运行 <code>stratis key list</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis key list</span></span>
<span class="line"><span>Key Description</span></span>
<span class="line"><span>pool1key</span></span></code></pre></div><p>这将验证是否创建了 <code>pool1key</code>。请注意，这些密钥不是持久的。如果主机重启，在访问加密的 Stratis 池之前，需要再次提供密钥（此过程将在后面介绍）。</p><p>如果你有多个加密池，它们可以有一个单独的密钥，也可以共享同一个密钥。</p><p>也可以使用以下 <code>keyctl</code> 命令查看密钥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># keyctl get_persistent @s</span></span>
<span class="line"><span>318044983</span></span>
<span class="line"><span># keyctl show</span></span>
<span class="line"><span>Session Keyring</span></span>
<span class="line"><span> 701701270 --alswrv      0     0  keyring: _ses</span></span>
<span class="line"><span> 649111286 --alswrv      0 65534   \\_ keyring: _uid.0</span></span>
<span class="line"><span> 318044983 ---lswrv      0 65534   \\_ keyring: _persistent.0</span></span>
<span class="line"><span>1051260141 --alswrv      0     0       \\_ user: stratis-1-key-pool1key</span></span></code></pre></div><h3 id="创建加密的-stratis-池" tabindex="-1">创建加密的 Stratis 池 <a class="header-anchor" href="#创建加密的-stratis-池" aria-label="Permalink to “创建加密的 Stratis 池”">​</a></h3><p>现在已经为 Stratis 创建了一个密钥，下一步是创建加密的 Stratis 池。加密池只能在创建池时进行。目前不可能对现有的池进行加密。</p><p>使用 <code>stratis pool create</code> 命令创建一个池。添加 <code>-key-desc</code> 和你在上一步提供的密钥描述（<code>pool1key</code>）。这将向 Stratis 发出信号，池应该使用提供的密钥进行加密。下面的例子是在 <code>/dev/vdb</code> 上创建 Stratis 池，并将其命名为 <code>pool1</code>。确保在你的系统中指定一个空的/可用的设备。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool create --key-desc pool1key pool1 /dev/vdb</span></span></code></pre></div><p>你可以使用 <code>stratis pool list</code> 命令验证该池是否已经创建：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool list</span></span>
<span class="line"><span>Name                     Total Physical   Properties</span></span>
<span class="line"><span>pool1   4.98 GiB / 37.63 MiB / 4.95 GiB      ~Ca, Cr</span></span></code></pre></div><p>在上面显示的示例输出中，<code>~Ca</code> 表示禁用了缓存（<code>~</code> 否定了该属性）。<code>Cr</code> 表示启用了加密。请注意，缓存和加密是相互排斥的。这两个功能不能同时启用。</p><p>接下来，创建一个文件系统。下面的例子演示了创建一个名为 <code>filesystem1</code> 的文件系统，将其挂载在 <code>/filesystem1</code> 挂载点上，并在新文件系统中创建一个测试文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis filesystem create pool1 filesystem1</span></span>
<span class="line"><span># mkdir /filesystem1</span></span>
<span class="line"><span># mount /stratis/pool1/filesystem1 /filesystem1</span></span>
<span class="line"><span># cd /filesystem1</span></span>
<span class="line"><span># echo &quot;this is a test file&quot; &gt; testfile</span></span></code></pre></div><h3 id="重启后访问加密池" tabindex="-1">重启后访问加密池 <a class="header-anchor" href="#重启后访问加密池" aria-label="Permalink to “重启后访问加密池”">​</a></h3><p>当重新启动时，你会发现 Stratis 不再显示你的加密池或它的块设备：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool list</span></span>
<span class="line"><span>Name   Total Physical   Properties</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis blockdev list</span></span>
<span class="line"><span>Pool Name   Device Node   Physical Size   Tier</span></span></code></pre></div><p>要访问加密池，首先要用之前使用的相同的密钥描述和密钥数据/口令重新创建密钥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis key set --capture-key pool1key</span></span>
<span class="line"><span>Enter desired key data followed by the return key:</span></span></code></pre></div><p>接下来，运行 <code>stratis pool unlock</code> 命令，并验证现在可以看到池和它的块设备：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool unlock</span></span>
<span class="line"><span># stratis pool list</span></span>
<span class="line"><span>Name                      Total Physical   Properties</span></span>
<span class="line"><span>pool1   4.98 GiB / 583.65 MiB / 4.41 GiB      ~Ca, Cr</span></span>
<span class="line"><span># stratis blockdev list</span></span>
<span class="line"><span>Pool Name   Device Node   Physical Size   Tier</span></span>
<span class="line"><span>pool1       /dev/dm-2          4.98 GiB   Data</span></span></code></pre></div><p>接下来，挂载文件系统并验证是否可以访问之前创建的测试文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount /stratis/pool1/filesystem1 /filesystem1/</span></span>
<span class="line"><span># cat /filesystem1/testfile</span></span>
<span class="line"><span>this is a test file</span></span></code></pre></div><h3 id="使用-systemd-单元文件在启动时自动解锁-stratis-池" tabindex="-1">使用 systemd 单元文件在启动时自动解锁 Stratis 池 <a class="header-anchor" href="#使用-systemd-单元文件在启动时自动解锁-stratis-池" aria-label="Permalink to “使用 systemd 单元文件在启动时自动解锁 Stratis 池”">​</a></h3><p>可以在启动时自动解锁 Stratis 池，无需手动干预。但是，必须有一个包含密钥的文件。在某些环境下，将密钥存储在文件中可能会有安全问题。</p><p>下图所示的 systemd 单元文件提供了一个简单的方法来在启动时解锁 Stratis 池并挂载文件系统。欢迎提供更好的/替代方法的反馈。你可以在文章末尾的评论区提供建议。</p><p>首先用下面的命令创建你的密钥文件。确保用之前输入的相同的密钥数据/密码来代替<code>passphrase</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo -n passphrase &gt; /root/pool1key</span></span></code></pre></div><p>确保该文件只能由 root 读取：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chmod 400 /root/pool1key</span></span>
<span class="line"><span># chown root:root /root/pool1key</span></span></code></pre></div><p>在 <code>/etc/systemd/system/stratis-filesystem1.service</code> 创建包含以下内容的 systemd 单元文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description = stratis mount pool1 filesystem1 file system</span></span>
<span class="line"><span>After = stratisd.service</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>ExecStartPre=sleep 2</span></span>
<span class="line"><span>ExecStartPre=stratis key set --keyfile-path /root/pool1key pool1key</span></span>
<span class="line"><span>ExecStartPre=stratis pool unlock</span></span>
<span class="line"><span>ExecStartPre=sleep 3</span></span>
<span class="line"><span>ExecStart=mount /stratis/pool1/filesystem1 /filesystem1</span></span>
<span class="line"><span>RemainAfterExit=yes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy = multi-user.target</span></span></code></pre></div><p>接下来，启用服务，使其在启动时运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl enable stratis-filesystem1.service</span></span></code></pre></div><p>现在重新启动并验证 Stratis 池是否已自动解锁，其文件系统是否已挂载。</p><h3 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to “结语”">​</a></h3><p>在今天的环境中，加密是很多人和组织的必修课。本篇文章演示了如何在 Stratis 2.1 中启用加密功能。</p><hr>`,50)),t("p",null,[s[8]||(s[8]=a("via: ",-1)),i(e,{href:"https://fedoramagazine.org/getting-started-with-stratis-encryption/"},{default:n(()=>[...s[7]||(s[7]=[a("https://fedoramagazine.org/getting-started-with-stratis-encryption/",-1)])]),_:1})]),t("p",null,[s[13]||(s[13]=a("作者：",-1)),i(e,{href:"https://fedoramagazine.org/author/briansmith/"},{default:n(()=>[...s[9]||(s[9]=[a("briansmith",-1)])]),_:1}),s[14]||(s[14]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[10]||(s[10]=[a("lujun9972",-1)])]),_:1}),s[15]||(s[15]=a(" 译者：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[11]||(s[11]=[a("wxy",-1)])]),_:1}),s[16]||(s[16]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[19]||(s[19]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[18]||(s[18]=[a("Linux中国",-1)])]),_:1}),s[21]||(s[21]=a(" 荣誉推出",-1))])])}const C=l(h,[["render",c]]);export{v as __pageData,C as default};
